function Stop-RrmTargetProcesses {
        param([Parameter(Mandatory = $true)][string]$Target)

        $targetNorm = [IO.Path]::GetFullPath($Target).TrimEnd('\')
        $excludeIds = @{}
        $walkId = [int]$PID
        for ($depth = 0; $depth -lt 12 -and $walkId -gt 0; $depth++) {
            $excludeIds[$walkId] = $true
            $procInfo = Get-CimInstance Win32_Process -Filter ("ProcessId={0}" -f $walkId) -ErrorAction SilentlyContinue
            if (-not $procInfo -or -not $procInfo.ParentProcessId -or [int]$procInfo.ParentProcessId -eq $walkId) { break }
